const s = $('Settings').first().json;
const urgent = String(s.urgentWords || '').split(',').map(w => w.trim().toLowerCase()).filter(Boolean);
const mails = $input.all().map(i => i.json).filter(m => m.id);
const esc = (x) => String(x || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = mails.map(m => {
  const from = m.From || (m.from && (m.from.text || m.from)) || '';
  const subject = m.Subject || m.subject || '(no subject)';
  const snippet = m.snippet || '';
  const hay = (subject + ' ' + snippet).toLowerCase();
  return { from: String(from), subject, snippet, isUrgent: urgent.some(w => hay.includes(w)),
           link: `https://mail.google.com/mail/u/0/#all/${m.id}` };
});
rows.sort((a, b) => (b.isUrgent - a.isUrgent) || a.from.localeCompare(b.from));
const line = (r) => `<li style="margin-bottom:6px">${r.isUrgent ? '<b style="color:#c0392b">[!]</b> ' : ''}<a href="${r.link}">${esc(r.subject)}</a><br><span style="color:#666">${esc(r.from)} - ${esc(r.snippet).slice(0, 140)}</span></li>`;
const nUrgent = rows.filter(r => r.isUrgent).length;
const html = rows.length
  ? `<p><b>${rows.length} unread</b> in ${esc(s.inboxLabel)} (${nUrgent} look urgent).</p><ol style="padding-left:18px">${rows.map(line).join('')}</ol>`
  : `<p>No unread email in ${esc(s.inboxLabel)} for this period.</p>`;
return [{ json: { to: s.digestTo, subject: `${s.inboxLabel}: ${rows.length} unread, ${nUrgent} urgent`, html } }];
